import assert from 'node:assert/strict';
import test from 'node:test';
import { computeDueDate } from '../lib/circulation/due-dates.js';
import { branchById } from '../lib/config/branches.js';

test('a book is due three weeks after it is lent', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-11-26', format: 'book', branch: branchById('central') });
  assert.equal(dueOn, '2026-12-17');
});

test('a due date that falls on a closed day moves to the next open day', () => {
  const dueOn = computeDueDate({
    checkedOutOn: '2026-11-22',
    format: 'dvd',
    branch: branchById('riverside'),
  });
  assert.equal(dueOn, '2026-12-01');
});

test('a due date that falls on a holiday of the branch moves to its next open day', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-04', format: 'book', branch: branchById('central') });
  assert.equal(dueOn, '2026-12-26');
});

test('a due date skips consecutive holidays of the branch', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-17', format: 'dvd', branch: branchById('riverside') });
  assert.equal(dueOn, '2026-12-26');
});

test('a due date skips a holiday followed by a closed weekend', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-18', format: 'dvd', branch: branchById('hillcrest') });
  assert.equal(dueOn, '2026-12-28');
});

test('a holiday of another branch does not move the due date', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-17', format: 'dvd', branch: branchById('central') });
  assert.equal(dueOn, '2026-12-24');
});

test('a laptop is due the next day', () => {
  const dueOn = computeDueDate({
    checkedOutOn: '2026-11-26',
    format: 'laptop',
    branch: branchById('hillcrest'),
  });
  assert.equal(dueOn, '2026-11-27');
});
import assert from 'node:assert/strict';
import test from 'node:test';
import { branchById } from '../lib/config/branches.js';
import { addDays, daysBetween, weekdayOf } from '../lib/helpers/dates.js';
import { isOpenOn, nextOpenDay } from '../lib/helpers/opening-days.js';

test('adds days across the end of a month and a year', () => {
  assert.equal(addDays('2026-11-26', 7), '2026-12-03');
  assert.equal(addDays('2026-12-30', 3), '2027-01-02');
  assert.equal(addDays('2026-03-01', -1), '2026-02-28');
});

test('counts the days between two dates', () => {
  assert.equal(daysBetween('2026-11-20', '2026-11-26'), 6);
  assert.equal(daysBetween('2026-11-26', '2026-11-20'), -6);
});

test('gives the day of the week, Sunday being 0', () => {
  assert.equal(weekdayOf('2026-11-29'), 0);
  assert.equal(weekdayOf('2026-11-26'), 4);
});

test('a branch is closed on its closed weekdays', () => {
  const riverside = branchById('riverside');
  assert.equal(isOpenOn(riverside, '2026-11-29'), false);
  assert.equal(isOpenOn(riverside, '2026-11-30'), false);
  assert.equal(isOpenOn(riverside, '2026-12-01'), true);
});

test('a branch is closed on its holidays', () => {
  assert.equal(isOpenOn(branchById('central'), '2026-12-25'), false);
  assert.equal(isOpenOn(branchById('central'), '2026-12-24'), true);
  assert.equal(isOpenOn(branchById('riverside'), '2026-12-24'), false);
});

test('the next open day of a closed day is the first day the branch opens again', () => {
  assert.equal(nextOpenDay(branchById('riverside'), '2026-11-29'), '2026-12-01');
  assert.equal(nextOpenDay(branchById('central'), '2026-11-26'), '2026-11-26');
});
